CREATE TABLE planes_diarios (id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),prediccion_modelo_origen_id BIGINT REFERENCES predicciones_modelo(id),fecha_objetivo DATE NOT NULL,estado VARCHAR(30) NOT NULL,energia_min_kcal NUMERIC(14,2),energia_max_kcal NUMERIC(14,2),proteina_min_g NUMERIC(14,2),proteina_max_g NUMERIC(14,2),carbohidratos_min_g NUMERIC(14,2),carbohidratos_max_g NUMERIC(14,2),grasas_min_g NUMERIC(14,2),grasas_max_g NUMERIC(14,2),motivo_no_disponible VARCHAR(1000),fuente_referencia VARCHAR(300),version_referencia VARCHAR(100),UNIQUE(cliente_id,fecha_objetivo));
CREATE TABLE cumplimientos_diarios (id BIGSERIAL PRIMARY KEY,plan_diario_id BIGINT NOT NULL UNIQUE REFERENCES planes_diarios(id),energia_estado VARCHAR(30),energia_consumido NUMERIC(14,2),energia_diferencia NUMERIC(14,2),energia_porcentaje NUMERIC(14,2),proteina_estado VARCHAR(30),proteina_consumido NUMERIC(14,2),proteina_diferencia NUMERIC(14,2),proteina_porcentaje NUMERIC(14,2),carbohidratos_estado VARCHAR(30),carbohidratos_consumido NUMERIC(14,2),carbohidratos_diferencia NUMERIC(14,2),carbohidratos_porcentaje NUMERIC(14,2),grasas_estado VARCHAR(30),grasas_consumido NUMERIC(14,2),grasas_diferencia NUMERIC(14,2),grasas_porcentaje NUMERIC(14,2));
CREATE TABLE detalles_evaluacion_consumo (id BIGSERIAL PRIMARY KEY,evaluacion_consumo_id BIGINT NOT NULL REFERENCES evaluaciones_consumo(id),criterio_evaluado_id BIGINT,componente VARCHAR(100),fuente VARCHAR(30),cantidad_observada NUMERIC(18,6),referencia_aplicada NUMERIC(18,6),referencia_aplicada_hasta NUMERIC(18,6),resultado VARCHAR(30),motivo_no_calculable VARCHAR(1000));
CREATE TABLE intervenciones_consumo_diarias (id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),evaluacion_consumo_id BIGINT NOT NULL REFERENCES evaluaciones_consumo(id),plan_diario_id BIGINT REFERENCES planes_diarios(id),criterio_evaluado_id BIGINT NOT NULL,componente VARCHAR(100),fuente_exceso VARCHAR(30),referencia_utilizada VARCHAR(1000),mensaje_estructurado VARCHAR(1000),UNIQUE(evaluacion_consumo_id,criterio_evaluado_id));
